function modal(html){
  const dialog=$('#modal'), content=$('#modalContent');
  content.innerHTML=`<button type="button" class="modal-close" aria-label="Cerrar ventana">×</button><div class="modal-scroll">${html}</div>`;
  const close=()=>dialog.close();
  content.querySelector('.modal-close')?.addEventListener('click',close,{once:true});
  if(!dialog.open) dialog.showModal();
  requestAnimationFrame(()=>{
    const first=content.querySelector('.modal-scroll input:not([type=hidden]):not([disabled]), .modal-scroll select:not([disabled]), .modal-scroll textarea:not([disabled]), .modal-scroll button:not(.modal-close):not([disabled])');
    first?.focus({preventScroll:true});
  });
}

// Close by clicking only the backdrop; keep clicks inside the card intact.
(()=>{
  const dialog=$('#modal');
  if(!dialog)return;
  dialog.addEventListener('click',e=>{
    const r=dialog.getBoundingClientRect();
    const inside=e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom;
    if(!inside)dialog.close();
  });
  dialog.addEventListener('close',()=>{
    const c=$('#modalContent');
    if(c)c.innerHTML='';
  });
})();

