const moduleDocs={
 dashboard:{title:'Cómo usar el resumen',steps:['Revisa los indicadores principales del negocio.','Comprueba el estado de WhatsApp, Telegram, Messenger e IA.','Sigue la configuración recomendada hasta completar la puesta en marcha.'],tip:'Los indicadores se actualizan con la actividad registrada dentro de Worktic.'},
 inbox:{title:'Cómo gestionar conversaciones',steps:['Selecciona una conversación en la columna izquierda.','Revisa el canal, historial y datos del contacto.','Escribe la respuesta o permite que el agente IA atienda según su configuración.','Marca, transfiere o continúa el seguimiento desde el CRM.'],tip:'Antes de enviar mensajes de seguimiento, confirma que existe consentimiento y que el canal lo permite.'},
 contacts:{title:'Cómo administrar contactos',steps:['Crea el contacto manualmente o deja que Worktic lo capture desde canales y formularios.','Completa teléfono, correo, etapa, etiquetas y notas.','Evita duplicados usando una sola ficha por persona.','Relaciona el contacto con oportunidades, citas y campañas.'],tip:'Mantener los datos completos mejora la asignación y el seguimiento comercial.'},
 pipeline:{title:'Cómo usar el pipeline',steps:['Crea una oportunidad para cada posibilidad de venta.','Ubícala en la etapa correcta.','Registra el valor estimado y el responsable.','Actualiza la etapa a medida que avanza la conversación.'],tip:'La IA puede sugerir acciones, pero las decisiones comerciales importantes deben ser revisadas.'},
 products:{title:'Cómo crear el catálogo',steps:['Agrega cada producto o servicio con descripción y precio.','Mantén actualizado el stock, cupos y estado.','Incluye respuestas frecuentes y condiciones comerciales.','Prueba al agente para confirmar que consulta el catálogo.'],tip:'La IA no debe inventar precios ni disponibilidad; mantén esta información al día.'},
 appointments:{title:'Cómo gestionar la agenda',steps:['Crea una cita indicando cliente, servicio, fecha y duración.','Confirma o reprograma según la respuesta del cliente.','Registra cancelaciones y asistencia.','Usa automatizaciones para recordatorios autorizados.'],tip:'Verifica siempre la zona horaria y evita cruces de horarios.'},
 agents:{title:'Cómo administrar múltiples agentes',steps:['Crea un agente por función o unidad comercial.','Define identidad, conocimiento, herramientas y presupuesto.','Asigna canales y crea reglas de enrutamiento.','Prueba cada agente y revisa métricas antes de activarlo.'],tip:'Mantén un agente principal activo como ruta de respaldo.'},
 agent:{title:'Cómo configurar el agente IA clásico',steps:['Define nombre, empresa, objetivo y tono.','Carga reglas e información verificada.','Activa respuestas automáticas únicamente cuando la prueba sea satisfactoria.','Usa el simulador con preguntas reales antes de publicarlo.'],tip:'Nunca incluyas secretos, contraseñas o datos sensibles en las instrucciones del agente.'},
 channels:{title:'Cómo conectar los canales',steps:['Elige el canal que deseas conectar.','Sigue la guía específica y valida las credenciales.','Realiza una prueba desde otra cuenta.','Revisa el estado y los errores de conexión.'],tip:'Los permisos oficiales de Meta son necesarios para funciones públicas de Messenger e Instagram.'},
 rules:{title:'Cómo crear automatizaciones',steps:['Define una frase o condición clara.','Escribe una respuesta específica y segura.','Activa la regla y pruébala.','Evita reglas demasiado generales que puedan responder fuera de contexto.'],tip:'Las reglas simples se ejecutan antes de invocar la IA.'},
 marketing:{title:'Cómo crear campañas',steps:['Selecciona orgánica, pagada o combinada según tu plan.','Define objetivo, producto, público y destino.','Genera la estrategia con IA y revísala.','Crea contenidos, formularios y atribución.','Publica solamente después de aprobar presupuesto y creativos.'],tip:'Las campañas pagadas requieren una cuenta publicitaria activa y permisos oficiales.'},
 landings:{title:'Cómo crear una landing premium',steps:['Pulsa Nueva landing y completa la información del negocio.','Genera contenido con IA o escribe el tuyo.','Selecciona plantilla, color, formulario y campaña relacionada.','Guarda como borrador y revisa la vista pública.','Activa Publicada cuando esté lista y comparte el enlace.'],tip:'Cada registro capturado por el formulario relacionado llega al módulo Leads y atribución.'},
 groups:{title:'Cómo trabajar con grupos',steps:['Registra únicamente grupos donde tu cuenta o bot tenga autorización.','Configura el modo de respuesta y las reglas.','Utiliza el buscador para encontrar comunidades públicas relevantes.','Revisa las normas antes de participar o publicar.'],tip:'Worktic no extrae miembros ni permite spam o ingreso automático a grupos.'},
 users:{title:'Cómo administrar el equipo',steps:['Crea usuarios según el límite del plan.','Asigna el rol mínimo necesario.','Revisa accesos cuando cambien las responsabilidades.','Desactiva cuentas que ya no deben entrar.'],tip:'No compartas una misma cuenta entre varias personas.'},
 billing:{title:'Cómo administrar el plan',steps:['Revisa el plan actual y los límites.','Selecciona una mejora cuando necesites más capacidad.','Realiza el pago en la red indicada y registra el hash.','Consulta el estado y la fecha de vencimiento.'],tip:'Confirma siempre la red y dirección antes de enviar USDT.'},
 admin:{title:'Cómo usar la administración global',steps:['Revisa usuarios, empresas, pagos y suscripciones.','Verifica pagos antes de aprobarlos.','Controla consumo, errores y vencimientos.','Registra cada intervención de soporte.'],tip:'El acceso de superadministrador debe protegerse con contraseña fuerte y 2FA en producción.'},
 setup:{title:'Cómo completar la puesta en marcha',steps:['Sigue las guías en el orden presentado.','Prueba cada canal de forma individual.','Configura el agente, catálogo y agenda.','Realiza una prueba completa desde lead hasta oportunidad.'],tip:'No abras la plataforma al público hasta completar las pruebas de seguridad y aislamiento.'}
};
function injectModuleDocs(){document.querySelectorAll('.view').forEach(v=>{const d=moduleDocs[v.id];if(!d||v.querySelector('.module-help'))return;const box=document.createElement('details');box.className='module-help';box.innerHTML=`<summary>Guía de este módulo: ${esc(d.title)}</summary><div class="module-help-body"><div><h3>Proceso recomendado</h3><ol>${d.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div><div class="help-tip"><b>Consejo importante</b><p>${esc(d.tip)}</p><p>Consulta también la sección <b>Guías</b> para la configuración técnica.</p></div></div>`;v.insertBefore(box,v.firstChild)})}
injectModuleDocs();

// ── V10: LANDING PAGES PREMIUM ────────────────────────────────
let allLandings=[],allLandingForms=[],allLandingCampaigns=[];
async function loadLandings(){
 [allLandings,allLandingForms,allLandingCampaigns]=await Promise.all([api('/api/marketing/landings'),api('/api/marketing/forms'),api('/api/marketing/campaigns')]);
 $('#landingsGrid').innerHTML=allLandings.length?allLandings.map(x=>`<article class="product-card landing-card" style="--landing-accent:${esc(x.accent||'#7c3aed')}"><div class="landing-preview"><small>${x.published?'PUBLICADA':'BORRADOR'} · ${esc(x.template)}</small><h3>${esc(x.headline||x.name)}</h3><span>${esc(x.subheadline||'')}</span></div><div class="section-head"><div><b>${esc(x.name)}</b><small>/l/${x.tenant_id}/${x.slug}</small></div><span class="pill ${x.published?'status-live':'status-draft'}">${x.published?'Activa':'Borrador'}</span></div><div class="actions"><button onclick="editLanding(${x.id})">Editar</button>${x.published?`<button class="secondary" onclick="window.open('/l/${x.tenant_id}/${x.slug}','_blank')">Ver pública</button>`:''}<button class="secondary" onclick="copyLanding(${x.id})">Copiar enlace</button><button class="danger" onclick="deleteLanding(${x.id})">Eliminar</button></div></article>`).join(''):'<article><h3>Crea tu primera landing premium</h3><p>Conecta la página con una campaña y un formulario para llevar cada lead al CRM.</p></article>';
}
$('#newLanding').onclick=()=>openLandingEditor({benefits_json:'["Respuesta inmediata","Atención personalizada","Proceso simple"]',features_json:'[{"title":"Beneficio principal","text":"Explica por qué tu oferta es valiosa."}]',testimonials_json:'[]',faq_json:'[]',accent:'#7c3aed',template:'aurora',primary_cta:'Solicitar información',primary_url:'#form'});
window.editLanding=id=>{const x=allLandings.find(a=>a.id===id);if(x)openLandingEditor(x)};
window.copyLanding=id=>{const x=allLandings.find(a=>a.id===id);if(x){navigator.clipboard.writeText(`${location.origin}/l/${x.tenant_id}/${x.slug}`);toast('Enlace copiado')}};
window.deleteLanding=async id=>{}; // redefinido en V13.1
function openLandingEditor(x={}){
 const formOptions='<option value="0">Sin formulario</option>'+allLandingForms.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('');
 const campOptions='<option value="0">Sin campaña</option>'+allLandingCampaigns.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');
 modal(`<h2>${x.id?'Editar':'Nueva'} landing premium</h2><div class="growth-tabs"><button type="button" class="active" data-lstep="content">Contenido</button><button type="button" data-lstep="sections">Secciones</button><button type="button" data-lstep="settings">Publicación</button></div><div id="lstep-content" class="landing-step"><label>Nombre interno<input id="lpName" value="${esc(x.name||'')}"></label><label>Producto o servicio<input id="lpProduct" placeholder="Describe la oferta para generar contenido"></label><div class="grid2"><label>Público ideal<input id="lpAudience"></label><label>Objetivo<input id="lpObjective" value="Capturar leads"></label></div><button type="button" id="generateLandingAI" class="secondary">Generar contenido con IA</button><label>Badge<input id="lpBadge" value="${esc(x.badge||'Solución profesional')}"></label><label>Título principal<textarea id="lpHeadline">${esc(x.headline||'')}</textarea></label><label>Subtítulo<textarea id="lpSubheadline">${esc(x.subheadline||'')}</textarea></label><div class="grid2"><label>CTA principal<input id="lpCTA" value="${esc(x.primary_cta||'Solicitar información')}"></label><label>Destino CTA<input id="lpCTAURL" value="${esc(x.primary_url||'#form')}"></label></div><label>Imagen principal (URL)<input id="lpHero" value="${esc(x.hero_image||'')}"></label></div><div id="lstep-sections" class="landing-step" hidden><label>Beneficios — JSON de textos<textarea class="codearea" id="lpBenefits">${esc(x.benefits_json||'[]')}</textarea></label><label>Características — JSON [{"title":"...","text":"..."}]<textarea class="codearea" id="lpFeatures">${esc(x.features_json||'[]')}</textarea></label><label>Testimonios — JSON [{"quote":"...","author":"..."}]<textarea class="codearea" id="lpTestimonials">${esc(x.testimonials_json||'[]')}</textarea></label><label>Preguntas frecuentes — JSON [{"question":"...","answer":"..."}]<textarea class="codearea" id="lpFAQ">${esc(x.faq_json||'[]')}</textarea></label></div><div id="lstep-settings" class="landing-step" hidden><div class="grid2"><label>Slug<input id="lpSlug" value="${esc(x.slug||'')}"></label><label>Plantilla<select id="lpTemplate"><option value="aurora">Aurora premium</option><option value="minimal">Minimal profesional</option><option value="bold">Comercial bold</option></select></label></div><div class="grid2"><label>Color principal<input id="lpAccent" type="color" value="${esc(x.accent||'#7c3aed')}"></label><label>Formulario relacionado<select id="lpForm">${formOptions}</select></label></div><label>Campaña relacionada<select id="lpCampaign">${campOptions}</select></label><label class="check"><input id="lpPublished" type="checkbox" ${x.published?'checked':''}> Publicar y hacer visible mediante enlace público</label><div class="notice">Guárdala primero como borrador, revisa textos, enlaces, políticas y formulario. Publica cuando todo esté aprobado.</div></div><div class="actions"><button type="button" id="saveLanding">Guardar landing</button><button value="cancel" class="secondary">Cancelar</button></div>`);
 $('#lpTemplate').value=x.template||'aurora';$('#lpForm').value=String(x.form_id||0);$('#lpCampaign').value=String(x.campaign_id||0);
 $$('[data-lstep]').forEach(b=>b.onclick=()=>{$$('[data-lstep]').forEach(a=>a.classList.remove('active'));b.classList.add('active');$$('.landing-step').forEach(a=>a.hidden=true);$('#lstep-'+b.dataset.lstep).hidden=false});
 $('#generateLandingAI').onclick=async()=>{const b=$('#generateLandingAI');b.disabled=true;b.textContent='Generando…';try{const r=await api('/api/marketing/landings/generate',{method:'POST',body:JSON.stringify({name:$('#lpName').value,product:$('#lpProduct').value,audience:$('#lpAudience').value,objective:$('#lpObjective').value,tone:'Profesional y comercial'})});if(r.raw){$('#lpSubheadline').value=r.raw}else{$('#lpHeadline').value=r.headline||'';$('#lpSubheadline').value=r.subheadline||'';$('#lpBadge').value=r.badge||'';$('#lpCTA').value=r.primary_cta||'Solicitar información';$('#lpBenefits').value=JSON.stringify(r.benefits||[],null,2);$('#lpFeatures').value=JSON.stringify(r.features||[],null,2);$('#lpTestimonials').value=JSON.stringify(r.testimonials||[],null,2);$('#lpFAQ').value=JSON.stringify(r.faq||[],null,2)}toast('Contenido generado. Revísalo antes de publicar.')}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='Generar contenido con IA'}};
 $('#saveLanding').onclick=async()=>{for(const id of ['lpBenefits','lpFeatures','lpTestimonials','lpFAQ']){try{JSON.parse($('#'+id).value||'[]')}catch{return toast('Corrige el JSON de las secciones')}}const d={id:x.id||0,name:$('#lpName').value,slug:$('#lpSlug').value,template:$('#lpTemplate').value,headline:$('#lpHeadline').value,subheadline:$('#lpSubheadline').value,badge:$('#lpBadge').value,primary_cta:$('#lpCTA').value,primary_url:$('#lpCTAURL').value,hero_image:$('#lpHero').value,benefits_json:$('#lpBenefits').value,features_json:$('#lpFeatures').value,testimonials_json:$('#lpTestimonials').value,faq_json:$('#lpFAQ').value,form_id:Number($('#lpForm').value),campaign_id:Number($('#lpCampaign').value),accent:$('#lpAccent').value,published:$('#lpPublished').checked};try{await api('/api/marketing/landings',{method:x.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();toast('Landing guardada');loadLandings()}catch(e){toast(e.message)}};
}


// V11 · navegación móvil premium
(()=>{
 const sidebar=$('#appSidebar'),backdrop=$('#menuBackdrop'),openBtn=$('#mobileMenuBtn'),closeBtn=$('#mobileMenuClose');
 const open=()=>{sidebar?.classList.add('mobile-open');backdrop?.classList.add('show');document.body.classList.add('menu-lock')};
 const close=()=>{sidebar?.classList.remove('mobile-open');backdrop?.classList.remove('show');document.body.classList.remove('menu-lock')};
 openBtn?.addEventListener('click',open);closeBtn?.addEventListener('click',close);backdrop?.addEventListener('click',close);
 $$('aside nav button').forEach(btn=>btn.addEventListener('click',()=>{
   const key=btn.dataset.view;if($('#mobileTitle')&&titles[key])$('#mobileTitle').textContent=titles[key][0];
   if(innerWidth<=820)close();
 }));
 addEventListener('resize',()=>{if(innerWidth>820)close()},{passive:true});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
})();


// ── V12: SISTEMA MULTIAGENTE ─────────────────────────────────
let aiAgents=[],agentRoutes=[],agentMetrics=[],agentPermissions=[];
$$('[data-agent-tab]').forEach(b=>b.onclick=()=>{$$('[data-agent-tab],.agent-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#agent-tab-'+b.dataset.agentTab).classList.add('active');if(b.dataset.agentTab==='routes')loadAgentRoutes();if(b.dataset.agentTab==='metrics')loadAgentMetrics();if(b.dataset.agentTab==='permissions')loadAgentPermissions()});
async function loadAIAgents(){
 const x=await api('/api/agents');aiAgents=x.agents||[];$('#agentPlan').textContent=`${x.plan}: ${aiAgents.length}/${x.limit} agentes`;
 $('#agentStats').innerHTML=[['Agentes',aiAgents.length],['Activos',aiAgents.filter(a=>a.status==='active').length],['Respuestas mes',aiAgents.reduce((n,a)=>n+(a.used_responses||0),0)],['Principal',aiAgents.find(a=>a.is_default)?.name||'Pendiente']].map(v=>`<div class="stat"><b>${esc(v[1])}</b><small>${v[0]}</small></div>`).join('');
 $('#newAIAgent').hidden=!x.can_manage;
 $('#agentsGrid').innerHTML=aiAgents.length?aiAgents.map(a=>`<article class="product-card"><div class="section-head"><div><small>${esc(a.type)} · ${esc(a.status)}</small><h3>${esc(a.name)}</h3></div>${a.is_default?'<span class="pill">Principal</span>':''}</div><p>${esc(a.objective||a.description||'Sin objetivo definido')}</p><p><b>Canales:</b> ${esc(a.channels||'Sin asignar')}</p><p><b>Consumo:</b> ${a.used_responses||0}${a.monthly_budget?` / ${a.monthly_budget}`:''} respuestas</p><div class="actions"><button onclick="editAIAgent(${a.id})">Editar</button><button class="secondary" onclick="testAIAgent(${a.id})">Probar</button>${!a.is_default?`<button class="danger" onclick="deleteAIAgent(${a.id})">Eliminar</button>`:''}</div></article>`).join(''):'<article><h3>Crea tu primer agente especializado</h3><p>Define un agente principal y después agrega ventas, soporte, agenda, campañas o comunidades según tu plan.</p></article>';
}
$('#newAIAgent').onclick=()=>openAIAgentEditor({type:'sales',tone:'Profesional y cercano',language:'es',status:'draft',tools:'contact,opportunity,appointment,handoff',channels:'',monthly_budget:0});
window.editAIAgent=id=>{const a=aiAgents.find(x=>x.id===id);if(a)openAIAgentEditor(a)};
function openAIAgentEditor(a={}){modal(`<h2>${a.id?'Editar':'Nuevo'} agente IA</h2><div class="form"><label>Nombre<input id="maName" value="${esc(a.name||'')}"></label><div class="grid2"><label>Tipo<select id="maType">${['general','sales','support','appointments','campaigns','community','custom'].map(x=>`<option ${a.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Estado<select id="maStatus"><option value="draft" ${a.status==='draft'?'selected':''}>Borrador</option><option value="active" ${a.status==='active'?'selected':''}>Activo</option><option value="paused" ${a.status==='paused'?'selected':''}>Pausado</option></select></label></div><label>Objetivo<textarea id="maObjective">${esc(a.objective||'')}</textarea></label><div class="grid2"><label>Tono<input id="maTone" value="${esc(a.tone||'Profesional y cercano')}"></label><label>Idioma<input id="maLanguage" value="${esc(a.language||'es')}"></label></div><label>Instrucciones<textarea id="maInstructions" rows="5">${esc(a.instructions||'')}</textarea></label><label>Conocimiento exclusivo<textarea id="maKnowledge" rows="5">${esc(a.knowledge||'')}</textarea></label><label>Herramientas permitidas<input id="maTools" value="${esc(a.tools||'')}"></label><label>Canales asignados<input id="maChannels" placeholder="whatsapp,telegram,messenger" value="${esc(a.channels||'')}"></label><div class="grid2"><label>Mensaje de bienvenida<textarea id="maGreeting">${esc(a.greeting||'')}</textarea></label><label>Reglas de transferencia<textarea id="maHandoff">${esc(a.handoff_rules||'')}</textarea></label></div><label>Presupuesto mensual de respuestas<input id="maBudget" type="number" min="0" value="${a.monthly_budget||0}"></label><label class="check"><input id="maDefault" type="checkbox" ${a.is_default?'checked':''}> Agente principal de respaldo</label><div class="actions"><button type="button" id="saveAIAgent">Guardar agente</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='saveAIAgent')return;document.removeEventListener('click',h);const d={...a,name:$('#maName').value,type:$('#maType').value,status:$('#maStatus').value,objective:$('#maObjective').value,tone:$('#maTone').value,language:$('#maLanguage').value,instructions:$('#maInstructions').value,knowledge:$('#maKnowledge').value,tools:$('#maTools').value,channels:$('#maChannels').value,greeting:$('#maGreeting').value,handoff_rules:$('#maHandoff').value,monthly_budget:Number($('#maBudget').value||0),is_default:$('#maDefault').checked};try{await api('/api/agents',{method:a.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();toast('Agente guardado');loadAIAgents()}catch(err){toast(err.message)} });}
window.testAIAgent=id=>{const a=aiAgents.find(x=>x.id===id);modal(`<h2>Probar ${esc(a?.name||'agente')}</h2><textarea id="maTestText" rows="5" placeholder="Escribe un mensaje real de cliente"></textarea><button type="button" id="runMATest">Probar respuesta</button><div id="maTestReply" class="reply"></div><button value="cancel" class="secondary">Cerrar</button>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='runMATest')return;document.removeEventListener('click',h);$('#maTestReply').textContent='Pensando…';try{const x=await api('/api/agents/test',{method:'POST',body:JSON.stringify({agent_id:id,text:$('#maTestText').value})});$('#maTestReply').textContent=x.reply}catch(err){$('#maTestReply').textContent=err.message}})};
window.deleteAIAgent=async id=>{}; // redefinido en V13.1
async function loadAgentRoutes(){agentRoutes=await api('/api/agents/routes');$('#agentRoutesTable').innerHTML=agentRoutes.length?`<div class="admin-table-wrap"><table class="table"><tr><th>Prioridad</th><th>Regla</th><th>Agente</th><th>Canal</th><th>Intención / palabra</th><th></th></tr>${agentRoutes.map(r=>`<tr><td>${r.priority}</td><td>${esc(r.name)}</td><td>${esc(aiAgents.find(a=>a.id===r.agent_id)?.name||r.agent_id)}</td><td>${esc(r.channel)}</td><td>${esc(r.intent||'')} ${esc(r.keyword||'')}</td><td><button class="danger" onclick="deleteAgentRoute(${r.id})">Eliminar</button></td></tr>`).join('')}</table></div>`:'<p>No hay reglas. El agente principal atiende como respaldo.</p>'}
$('#newAgentRoute').onclick=()=>{if(!aiAgents.length)return toast('Crea primero un agente');modal(`<h2>Nueva regla de enrutamiento</h2><div class="form"><label>Nombre<input id="arName"></label><label>Agente<select id="arAgent">${aiAgents.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><div class="grid2"><label>Prioridad<input id="arPriority" type="number" value="100"></label><label>Canal<select id="arChannel"><option value="*">Todos</option><option>whatsapp</option><option>telegram</option><option>messenger</option><option>landing</option><option>group</option></select></label></div><div class="grid2"><label>Intención<input id="arIntent" placeholder="sales, support, appointment"></label><label>Palabra clave<input id="arKeyword"></label></div><button type="button" id="saveAgentRoute">Guardar regla</button><button value="cancel" class="secondary">Cancelar</button></div>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='saveAgentRoute')return;document.removeEventListener('click',h);try{await api('/api/agents/routes',{method:'POST',body:JSON.stringify({name:$('#arName').value,agent_id:Number($('#arAgent').value),priority:Number($('#arPriority').value),channel:$('#arChannel').value,intent:$('#arIntent').value,keyword:$('#arKeyword').value,enabled:true})});$('#modal').close();loadAgentRoutes();toast('Regla creada')}catch(err){toast(err.message)}})};
window.deleteAgentRoute=async id=>{await api('/api/agents/routes?id='+id,{method:'DELETE'});loadAgentRoutes()};
async function loadAgentMetrics(){const period=$('#agentMetricPeriod').value||new Date().toISOString().slice(0,7),x=await api('/api/agents/metrics?period='+period);agentMetrics=x.metrics||[];$('#agentMetricsTable').innerHTML=`<div class="admin-table-wrap"><table class="table"><tr><th>Agente</th><th>Conversaciones</th><th>Respuestas</th><th>Tokens</th><th>Errores</th><th>Costo est.</th></tr>${agentMetrics.map(m=>`<tr><td>${esc(m.name)}</td><td>${m.conversations}</td><td>${m.responses}</td><td>${(m.input_tokens||0)+(m.output_tokens||0)}</td><td>${m.errors}</td><td>${Number(m.estimated_cost||0).toFixed(4)} USD</td></tr>`).join('')}</table></div>`}
$('#agentMetricPeriod').value=new Date().toISOString().slice(0,7);$('#agentMetricPeriod').onchange=loadAgentMetrics;
async function loadAgentPermissions(){try{agentPermissions=await api('/api/agents/permissions');$('#agentPermissionsTable').innerHTML=agentPermissions.length?`<div class="admin-table-wrap"><table class="table"><tr><th>Agente</th><th>Usuario</th><th>Rol</th><th>Ver</th><th>Editar</th><th>Probar</th><th>Pausar</th></tr>${agentPermissions.map(p=>`<tr><td>${esc(aiAgents.find(a=>a.id===p.agent_id)?.name||p.agent_id)}</td><td>${esc(p.name)}</td><td>${esc(p.role)}</td><td>${p.can_view?'✓':'—'}</td><td>${p.can_edit?'✓':'—'}</td><td>${p.can_test?'✓':'—'}</td><td>${p.can_pause?'✓':'—'}</td></tr>`).join('')}</table></div>`:'<p>No hay permisos específicos. Se aplican los permisos generales por rol.</p>'}catch(e){$('#agentPermissionsTable').textContent=e.message}}
$('#newAgentPermission').onclick=async()=>{if(!aiAgents.length)return toast('Crea primero un agente');let users=[];try{users=await api('/api/admin/users')}catch(e){return toast(e.message)}modal(`<h2>Asignar permisos</h2><div class="form"><label>Agente<select id="apAgent">${aiAgents.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><label>Usuario<select id="apUser">${users.map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(u.role)}</option>`).join('')}</select></label><label class="check"><input id="apView" type="checkbox" checked> Ver</label><label class="check"><input id="apEdit" type="checkbox"> Editar</label><label class="check"><input id="apTest" type="checkbox" checked> Probar</label><label class="check"><input id="apPause" type="checkbox"> Pausar</label><button type="button" id="saveAgentPermission">Guardar</button><button value="cancel" class="secondary">Cancelar</button></div>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='saveAgentPermission')return;document.removeEventListener('click',h);try{await api('/api/agents/permissions',{method:'POST',body:JSON.stringify({AgentID:Number($('#apAgent').value),UserID:Number($('#apUser').value),CanView:$('#apView').checked,CanEdit:$('#apEdit').checked,CanTest:$('#apTest').checked,CanPause:$('#apPause').checked})});$('#modal').close();loadAgentPermissions();toast('Permisos guardados')}catch(err){toast(err.message)}})};

// V13.1 — UI profesional, CRUD consistente e invitaciones por WhatsApp
function professionalConfirm({title='Confirmar acción',message='',confirmText='Confirmar',danger=false}={}){
 return new Promise(resolve=>{modal(`<div class="modal-icon ${danger?'danger':'info'}">${danger?'!':'✓'}</div><h2>${esc(title)}</h2><p class="modal-copy">${esc(message)}</p><div class="actions modal-actions"><button type="button" id="professionalConfirmBtn" class="${danger?'danger':''}">${esc(confirmText)}</button><button value="cancel" class="secondary">Cancelar</button></div>`);const d=$('#modal');const done=v=>{d.close();resolve(v)};$('#professionalConfirmBtn').onclick=()=>done(true);d.addEventListener('close',()=>resolve(false),{once:true})})
}
function formError(msg){let e=$('#modalFormError');if(!e){e=document.createElement('div');e.id='modalFormError';e.className='form-error';$('#modalContent').prepend(e)}e.textContent=msg;e.hidden=false}

let crmContactsCache=[],opportunitiesCache=[];
async function loadContacts(){crmContactsCache=await api('/api/crm/contacts');$('#contactsTable').innerHTML=crmContactsCache.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Cliente</th><th>Contacto</th><th>Canal</th><th>Etapa</th><th>Etiquetas</th><th>Acciones</th></tr>${crmContactsCache.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.email||'Sin correo')}</small></td><td>${esc(x.phone||'—')}</td><td><span class="soft-badge">${esc(x.channel||'manual')}</span></td><td>${esc(x.stage||'Nuevo')}</td><td>${esc(x.tags||'—')}</td><td><div class="row-actions"><button class="secondary" onclick="contactFormById(${x.id})">Editar</button><button class="danger ghost-danger" onclick="deleteCRMContact(${x.id})">Eliminar</button></div></td></tr>`).join('')}</table></div>`:'<div class="empty-state"><b>Aún no tienes contactos</b><p>Crea el primero o deja que Worktic los capture desde conversaciones, formularios y campañas.</p><button onclick="openContactForm({})">Nuevo contacto</button></div>'}
$('#newContact').onclick=()=>openContactForm({channel:'manual',stage:'Nuevo'});
window.contactFormById=id=>openContactForm(crmContactsCache.find(x=>x.id===id)||{});
window.openContactForm=x=>{modal(`<div class="modal-heading"><span class="eyebrow">CRM</span><h2>${x.id?'Editar':'Nuevo'} contacto</h2><p>Conserva la información comercial organizada y disponible para el equipo.</p></div><div class="form"><div class="grid2"><label>Nombre<input id="cfName" value="${esc(x.name||'')}" required></label><label>Teléfono<input id="cfPhone" value="${esc(x.phone||'')}" placeholder="573001234567"></label></div><label>Correo<input id="cfEmail" type="email" value="${esc(x.email||'')}"></label><div class="grid2"><label>Canal<select id="cfChannel">${['manual','whatsapp','telegram','messenger','landing','form'].map(v=>`<option ${x.channel===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Etapa<select id="cfStage">${['Nuevo','Contactado','Interesado','Calificado','Cotización','Negociación','Ganado','Perdido'].map(v=>`<option ${x.stage===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Etiquetas<input id="cfTags" value="${esc(x.tags||'')}" placeholder="vip, medellín, estética"></label><label>Notas<textarea id="cfNotes" rows="4">${esc(x.notes||'')}</textarea></label><div class="actions"><button type="button" id="saveCRMContact">Guardar contacto</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#saveCRMContact').onclick=async()=>{const d={...x,name:$('#cfName').value.trim(),phone:$('#cfPhone').value.trim(),email:$('#cfEmail').value.trim(),channel:$('#cfChannel').value,stage:$('#cfStage').value,tags:$('#cfTags').value.trim(),notes:$('#cfNotes').value.trim()};if(!d.name)return formError('Escribe el nombre del contacto.');try{await api('/api/crm/contacts',{method:x.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();toast('Contacto guardado');loadContacts()}catch(e){formError(e.message)}}};
window.deleteCRMContact=async id=>{if(!await professionalConfirm({title:'Eliminar contacto',message:'Esta acción elimina la ficha del CRM. Las conversaciones del canal no se borrarán.',confirmText:'Eliminar',danger:true}))return;await api('/api/crm/contacts?id='+id,{method:'DELETE'});toast('Contacto eliminado');loadContacts()};

async function loadOpps(){opportunitiesCache=await api('/api/crm/opportunities');$('#pipelineBoard').innerHTML=stages.map(s=>`<div class="column"><div class="column-head"><b>${s}</b><span>${opportunitiesCache.filter(x=>x.stage===s).length}</span></div>${opportunitiesCache.filter(x=>x.stage===s).map(x=>`<div class="card pipeline-card"><div><b>${esc(x.title)}</b><small>${esc(x.owner||'Sin asignar')}</small></div><strong>$${Number(x.value||0).toLocaleString()}</strong><div class="row-actions"><button class="secondary" onclick="opportunityFormById(${x.id})">Editar</button><button class="danger ghost-danger" onclick="deleteOpportunity(${x.id})">Eliminar</button></div></div>`).join('')}</div>`).join('')}
$('#newOpp').onclick=()=>openOpportunityForm({stage:'Nuevo',value:0});
window.opportunityFormById=id=>openOpportunityForm(opportunitiesCache.find(x=>x.id===id)||{});
window.openOpportunityForm=x=>{modal(`<div class="modal-heading"><span class="eyebrow">PIPELINE</span><h2>${x.id?'Editar':'Nueva'} oportunidad</h2><p>Registra valor, etapa y responsable para mantener el seguimiento.</p></div><div class="form"><label>Nombre de la oportunidad<input id="ofTitle" value="${esc(x.title||'')}"></label><div class="grid2"><label>Valor estimado<input id="ofValue" type="number" min="0" value="${x.value||0}"></label><label>Etapa<select id="ofStage">${stages.map(v=>`<option ${x.stage===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Responsable<input id="ofOwner" value="${esc(x.owner||'')}"></label><label>ID de contacto relacionado<input id="ofContact" type="number" min="0" value="${x.contact_id||0}"></label><div class="actions"><button type="button" id="saveOpportunity">Guardar oportunidad</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#saveOpportunity').onclick=async()=>{const d={...x,title:$('#ofTitle').value.trim(),value:Number($('#ofValue').value||0),stage:$('#ofStage').value,owner:$('#ofOwner').value.trim(),contact_id:Number($('#ofContact').value||0)};if(!d.title)return formError('Escribe el nombre de la oportunidad.');try{await api('/api/crm/opportunities',{method:x.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();toast('Oportunidad guardada');loadOpps()}catch(e){formError(e.message)}}};
window.deleteOpportunity=async id=>{if(!await professionalConfirm({title:'Eliminar oportunidad',message:'Se eliminará esta oportunidad del pipeline.',confirmText:'Eliminar',danger:true}))return;await api('/api/crm/opportunities?id='+id,{method:'DELETE'});toast('Oportunidad eliminada');loadOpps()};

window.connectTenantChannel=async c=>{if(c.type==='whatsapp_qr'){try{await api('/api/channels/action',{method:'POST',body:JSON.stringify({id:c.id,action:'connect',agent_id:c.assigned_agent_id||0})});toast('Generando QR exclusivo');pollTenantQR(c.id)}catch(e){toast(e.message)}return}const isTG=c.type==='telegram';modal(`<div class="modal-heading"><span class="eyebrow">CONEXIÓN SEGURA</span><h2>Conectar ${isTG?'Telegram':'Facebook Messenger'}</h2><p>Las credenciales se cifran y quedan asociadas únicamente a este espacio.</p></div><div class="form"><label>${isTG?'Token de BotFather':'Page Access Token'}<input id="channelToken" type="password" autocomplete="off"></label><label>${isTG?'Usuario del bot, sin @':'Page ID'}<input id="channelExternal"></label><div class="actions"><button type="button" id="saveChannelCredentials">Conectar canal</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#saveChannelCredentials').onclick=async()=>{const token=$('#channelToken').value.trim(),external_id=$('#channelExternal').value.trim();if(!token||!external_id)return formError('Completa los dos campos.');try{await api('/api/channels/action',{method:'POST',body:JSON.stringify({id:c.id,action:'connect',token,external_id,agent_id:c.assigned_agent_id||0})});$('#modal').close();toast('Canal conectado');loadChannels()}catch(e){formError(e.message)}}};
window.deleteTenantChannel=async id=>{if(!await professionalConfirm({title:'Eliminar conexión',message:'La referencia de esta conexión será eliminada. Revisa antes si tiene conversaciones activas.',confirmText:'Eliminar conexión',danger:true}))return;await api('/api/channels/connections?id='+id,{method:'DELETE'});toast('Conexión eliminada');loadChannels()};

async function loadUsers(){try{const [xs,inv,profile]=await Promise.all([api('/api/admin/users'),api('/api/team/invitations'),api('/api/account/profile')]);const max=Number(profile.plan?.max_users||1),used=xs.filter(x=>x.active).length,pending=inv.filter(x=>x.status==='pending'&&new Date(x.expires_at)>new Date()).length;$('#teamUsage').innerHTML=[['Miembros activos',used],['Invitaciones pendientes',pending],['Cupos disponibles',Math.max(0,max-used-pending)]].map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('');$('#usersTable').innerHTML=xs.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Miembro</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr>${xs.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.email)}</small></td><td><span class="soft-badge">${esc(roleLabel(x.role))}</span></td><td><span class="status-dot ${x.active?'ok':'off'}"></span>${x.active?'Activo':'Suspendido'}</td><td><div class="row-actions"><button class="secondary" onclick="editTeamUser(${x.id})">Editar</button>${x.id!==window.currentUser?.id?`<button class="danger ghost-danger" onclick="deleteUser(${x.id})">Eliminar</button>`:''}</div></td></tr>`).join('')}</table></div>`:'<div class="empty-state"><b>No hay integrantes</b></div>';$('#teamInvitations').innerHTML=inv.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Invitado</th><th>Rol / área</th><th>Estado</th><th>Vence</th><th></th></tr>${inv.map(i=>`<tr><td><b>${esc(i.name)}</b><small>+${esc(i.phone)}</small></td><td>${esc(roleLabel(i.role))}<small>${esc(i.area||'General')}</small></td><td><span class="soft-badge">${esc(i.status)}</span></td><td>${new Date(i.expires_at).toLocaleString()}</td><td>${i.status==='pending'?`<button class="danger ghost-danger" onclick="cancelTeamInvite(${i.id})">Cancelar</button>`:'—'}</td></tr>`).join('')}</table></div>`:'<div class="empty-state compact"><b>No hay invitaciones pendientes</b><p>Usa “Invitar por WhatsApp” para incorporar a tu equipo.</p></div>'}catch(e){$('#usersTable').innerHTML=`<div class="notice">${esc(e.message)}</div>`}}
$('#inviteTeamMember').onclick=()=>{modal(`<div class="modal-heading"><span class="eyebrow">EQUIPO</span><h2>Invitar por WhatsApp</h2><p>Worktic creará un enlace seguro de un solo uso y abrirá WhatsApp con el mensaje listo.</p></div><div class="form"><div class="grid2"><label>Nombre<input id="tiName"></label><label>WhatsApp internacional<input id="tiPhone" placeholder="573001234567"></label></div><div class="grid2"><label>Rol<select id="tiRole"><option value="agent">Asesor</option><option value="supervisor">Supervisor</option><option value="admin">Administrador</option></select></label><label>Área<input id="tiArea" placeholder="Ventas, soporte, agenda..."></label></div><div class="permission-preview"><b>Acceso según rol</b><p id="tiRoleHelp">Atenderá conversaciones asignadas, contactos, oportunidades y citas.</p></div><div class="actions"><button type="button" id="createTeamInvite">Crear y abrir WhatsApp</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#tiRole').onchange=e=>{$('#tiRoleHelp').textContent={agent:'Atenderá conversaciones asignadas, contactos, oportunidades y citas.',supervisor:'Podrá supervisar conversaciones, asesores, oportunidades y métricas.',admin:'Podrá administrar la operación, agentes y canales, sin controlar propiedad crítica.'}[e.target.value]};$('#createTeamInvite').onclick=async()=>{const d={name:$('#tiName').value.trim(),phone:$('#tiPhone').value.trim(),role:$('#tiRole').value,area:$('#tiArea').value.trim()};if(!d.name||!d.phone)return formError('Completa nombre y WhatsApp internacional.');try{const x=await api('/api/team/invitations',{method:'POST',body:JSON.stringify(d)});$('#modal').close();loadUsers();toast('Invitación creada');window.open(x.whatsapp_url,'_blank','noopener')}catch(e){formError(e.message)}}};
window.editTeamUser=async id=>{const xs=await api('/api/admin/users'),x=xs.find(u=>u.id===id);if(!x)return;modal(`<div class="modal-heading"><span class="eyebrow">MIEMBRO</span><h2>Editar acceso</h2><p>${esc(x.email)}</p></div><div class="form"><label>Nombre<input id="euName" value="${esc(x.name)}"></label><label>Rol<select id="euRole">${['owner','admin','supervisor','agent'].map(r=>`<option value="${r}" ${x.role===r?'selected':''}>${roleLabel(r)}</option>`).join('')}</select></label><label class="switch-row"><span><b>Acceso activo</b><small>Al suspenderlo no podrá iniciar sesión.</small></span><input id="euActive" type="checkbox" ${x.active?'checked':''}></label><div class="actions"><button type="button" id="saveTeamUser">Guardar cambios</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#saveTeamUser').onclick=async()=>{try{await api('/api/admin/users',{method:'PUT',body:JSON.stringify({id,name:$('#euName').value.trim(),role:$('#euRole').value,company:x.company,active:$('#euActive').checked})});$('#modal').close();toast('Miembro actualizado');loadUsers()}catch(e){formError(e.message)}}};
window.deleteUser=async id=>{if(!await professionalConfirm({title:'Eliminar miembro',message:'Este usuario perderá el acceso al espacio empresarial. La información comercial compartida permanecerá en la empresa.',confirmText:'Eliminar acceso',danger:true}))return;await api('/api/admin/users?id='+id,{method:'DELETE'});toast('Miembro eliminado');loadUsers()};
window.cancelTeamInvite=async id=>{if(!await professionalConfirm({title:'Cancelar invitación',message:'El enlace dejará de funcionar inmediatamente.',confirmText:'Cancelar invitación',danger:true}))return;await api('/api/team/invitations?id='+id,{method:'DELETE'});toast('Invitación cancelada');loadUsers()};

window.deleteProduct=async id=>{if(!await professionalConfirm({title:'Eliminar producto',message:'La IA dejará de consultar este producto o servicio.',confirmText:'Eliminar',danger:true}))return;await api('/api/products?id='+id,{method:'DELETE'});toast('Producto eliminado');loadProducts()};
window.deleteCampaign=async id=>{if(!await professionalConfirm({title:'Eliminar campaña',message:'Se eliminará la campaña y dejará de aparecer en el panel.',confirmText:'Eliminar',danger:true}))return;await api('/api/marketing/campaigns?id='+id,{method:'DELETE'});loadMarketing()};
window.deleteGroup=async id=>{if(!await professionalConfirm({title:'Eliminar grupo',message:'Se quitará de Worktic, sin eliminar el grupo en la plataforma externa.',confirmText:'Eliminar',danger:true}))return;await api('/api/groups?id='+id,{method:'DELETE'});loadGroups()};
window.sendGroupMessage=id=>{modal(`<div class="modal-heading"><span class="eyebrow">COMUNIDAD</span><h2>Enviar mensaje al grupo</h2><p>Utiliza contenido autorizado y respeta las reglas de la comunidad.</p></div><div class="form"><label>Mensaje<textarea id="groupMessageText" rows="6"></textarea></label><div class="actions"><button type="button" id="sendProfessionalGroupMessage">Enviar mensaje</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#sendProfessionalGroupMessage').onclick=async()=>{const text=$('#groupMessageText').value.trim();if(!text)return formError('Escribe el mensaje.');try{await api('/api/groups/send',{method:'POST',body:JSON.stringify({group_id:id,text})});$('#modal').close();toast('Mensaje enviado')}catch(e){formError(e.message)}}};
window.deleteLanding=async id=>{if(!await professionalConfirm({title:'Eliminar landing page',message:'El enlace público dejará de funcionar y esta acción no se puede deshacer.',confirmText:'Eliminar landing',danger:true}))return;await api('/api/marketing/landings?id='+id,{method:'DELETE'});toast('Landing eliminada');loadLandings()};
window.deleteAIAgent=async id=>{if(!await professionalConfirm({title:'Eliminar agente IA',message:'También se eliminarán sus reglas relacionadas. El agente principal no puede eliminarse.',confirmText:'Eliminar agente',danger:true}))return;try{await api('/api/agents?id='+id,{method:'DELETE'});toast('Agente eliminado');loadAIAgents()}catch(e){toast(e.message)}};

let automationRulesCache=[];
async function loadRules(){automationRulesCache=await api('/api/rules');$('#rulesList').innerHTML=automationRulesCache.length?automationRulesCache.map(r=>`<div class="card automation-card"><div class="top"><div><b>${esc(r.name)}</b><small>${r.enabled?'Activa':'Pausada'}</small></div><span class="soft-badge">${esc(r.match_type)}</span></div><p><b>${esc(r.keyword)}</b> → ${esc(r.response)}</p><div class="row-actions"><button class="secondary" onclick="editAutomationRule(${r.id})">Editar</button><button class="danger ghost-danger" onclick="delRule(${r.id})">Eliminar</button></div></div>`).join(''):'<div class="empty-state compact"><b>No hay automatizaciones</b><p>Crea reglas sencillas para responder antes de invocar a la IA.</p></div>'}
window.editAutomationRule=id=>{const r=automationRulesCache.find(x=>x.id===id);if(!r)return;modal(`<div class="modal-heading"><span class="eyebrow">AUTOMATIZACIÓN</span><h2>Editar regla</h2><p>Ajusta la condición y la respuesta automática.</p></div><div class="form"><label>Nombre<input id="erName" value="${esc(r.name)}"></label><div class="grid2"><label>Coincidencia<select id="erType"><option value="contains" ${r.match_type==='contains'?'selected':''}>Contiene</option><option value="exact" ${r.match_type==='exact'?'selected':''}>Exacta</option><option value="starts" ${r.match_type==='starts'?'selected':''}>Empieza por</option></select></label><label>Palabra o frase<input id="erKeyword" value="${esc(r.keyword)}"></label></div><label>Respuesta<textarea id="erResponse" rows="5">${esc(r.response)}</textarea></label><label class="switch-row"><span><b>Regla activa</b><small>Puede pausarse sin eliminarla.</small></span><input id="erEnabled" type="checkbox" ${r.enabled?'checked':''}></label><div class="actions"><button type="button" id="saveEditedRule">Guardar cambios</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#saveEditedRule').onclick=async()=>{const d={...r,name:$('#erName').value.trim(),match_type:$('#erType').value,keyword:$('#erKeyword').value.trim(),response:$('#erResponse').value.trim(),enabled:$('#erEnabled').checked};if(!d.name||!d.keyword||!d.response)return formError('Completa nombre, condición y respuesta.');try{await api('/api/rules',{method:'PUT',body:JSON.stringify(d)});$('#modal').close();toast('Automatización actualizada');loadRules()}catch(e){formError(e.message)}}};
window.delRule=async id=>{if(!await professionalConfirm({title:'Eliminar automatización',message:'La regla dejará de responder inmediatamente.',confirmText:'Eliminar',danger:true}))return;await api('/api/rules?id='+id,{method:'DELETE'});toast('Automatización eliminada');loadRules()};

async function loadAppointments(){const xs=await api('/api/appointments');$('#appointmentsTable').innerHTML=xs.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Fecha</th><th>Cliente</th><th>Servicio</th><th>Estado</th><th>Acciones</th></tr>${xs.map(x=>`<tr><td>${new Date(x.starts_at).toLocaleString()}</td><td><b>${esc(x.contact_name)}</b><small>${esc(x.contact_phone)}</small></td><td>${esc(x.service)}</td><td><span class="soft-badge">${esc(x.status)}</span></td><td><div class="row-actions"><button class="secondary" onclick='appointmentForm(${JSON.stringify(x)})'>Editar</button><button class="danger ghost-danger" onclick="deleteAppointment(${x.id})">Eliminar</button></div></td></tr>`).join('')}</table></div>`:'<div class="empty-state"><b>No hay citas</b><p>Registra una cita manualmente o permite que el agente IA la cree.</p><button onclick="appointmentForm({duration_minutes:30,status:\'Programada\'})">Nueva cita</button></div>'}
window.deleteAppointment=async id=>{if(!await professionalConfirm({title:'Eliminar cita',message:'La cita será eliminada de la agenda. Considera cancelarla si necesitas conservar el historial.',confirmText:'Eliminar',danger:true}))return;await api('/api/appointments?id='+id,{method:'DELETE'});toast('Cita eliminada');loadAppointments()};

window.reviewPayment=(id,action)=>{modal(`<div class="modal-heading"><span class="eyebrow">VERIFICACIÓN DE PAGO</span><h2>${action==='approve'?'Aprobar pago':'Rechazar pago'}</h2><p>${action==='approve'?'Confirma que verificaste red, token, destino, monto y confirmaciones.':'Registra un motivo claro para el cliente.'}</p></div><div class="form"><label>Nota administrativa<textarea id="paymentReviewNote" rows="4" placeholder="${action==='approve'?'Opcional':'Motivo del rechazo'}"></textarea></label><div class="actions"><button type="button" id="confirmPaymentReview" class="${action==='reject'?'danger':''}">${action==='approve'?'Aprobar y activar plan':'Rechazar pago'}</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#confirmPaymentReview').onclick=async()=>{const note=$('#paymentReviewNote').value.trim();if(action==='reject'&&!note)return formError('Escribe el motivo del rechazo.');try{await api('/api/admin/payments',{method:'PUT',body:JSON.stringify({id,action,note})});$('#modal').close();toast(action==='approve'?'Plan activado':'Pago rechazado');loadAdmin()}catch(e){formError(e.message)}}};


// ── SOCIAL HUB PREMIUM ──────────────────────────────────────
let socialPosts=[],socialConnections=[],socialOverview={},socialAnalytics={},socialCalendarDate=new Date();
const socialPlatformMeta={facebook:['Facebook','F'],instagram:['Instagram','◎'],linkedin:['LinkedIn','in'],telegram:['Telegram','✈'],tiktok:['TikTok','♪'],youtube:['YouTube','▶']};
function socialBadge(p){const m=socialPlatformMeta[p]||[p,'•'];return `<span class="platform-badge ${p}"><i>${m[1]}</i>${m[0]}</span>`}
async function loadSocialHub(){
 try{[socialOverview,socialPosts,socialConnections,socialAnalytics]=await Promise.all([api('/api/social/overview'),api('/api/social/posts'),api('/api/social/connections'),api('/api/social/analytics')]);renderSocialStats();renderSocialOverview();applySocialPermissions();renderSocialConnections();renderSocialPosts();renderSocialCalendar();renderSocialAnalytics();ensureSocialComposer()}catch(e){toast(e.message)}
}
function renderSocialStats(){const items=[['Redes conectadas',socialOverview.connections||0],['Programadas',socialOverview.scheduled||0],['Publicadas',socialOverview.published||0],['Con error',socialOverview.failed||0]];$('#socialStats').innerHTML=items.map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('')}
function renderSocialOverview(){const upcoming=socialPosts.filter(x=>['scheduled','queued'].includes(x.status)).slice(0,5);$('#socialUpcoming').innerHTML=upcoming.length?upcoming.map(x=>`<div class="upcoming-row">${socialBadge(x.platform)}<div><b>${esc(x.title||'Publicación')}</b><small>${x.scheduled_at?new Date(x.scheduled_at).toLocaleString():'Publicación inmediata'}</small></div><span class="status-chip ${x.status}">${x.status}</span></div>`).join(''):'<div class="empty-premium"><b>Tu calendario está libre</b><p>Crea la primera publicación multicanal.</p><button onclick="openSocialComposer()">Crear contenido</button></div>';
 const platforms=Object.keys(socialPlatformMeta);$('#socialNetworkHealth').innerHTML=platforms.map(p=>{const c=socialConnections.find(x=>x.platform===p&&x.status==='connected');return `<div class="network-row">${socialBadge(p)}<span class="connection-dot ${c?'on':''}"></span><small>${c?esc(c.account_name):'Sin conectar'}</small></div>`}).join('')}
function switchSocialTab(tab){$$('[data-social-tab]').forEach(x=>x.classList.toggle('active',x.dataset.socialTab===tab));$$('.social-panel').forEach(x=>x.classList.toggle('active',x.id==='social-'+tab));if(tab==='calendar')renderSocialCalendar();if(tab==='composer')ensureSocialComposer();if(tab==='analytics')loadSocialAnalytics()}
function socialPerm(k){return !!(socialOverview.permissions||{})[k]}
function applySocialPermissions(){const manage=socialPerm('manage_connections'),create=socialPerm('create_draft');['socialConnect','socialConnect2'].forEach(id=>{const e=$('#'+id);if(e)e.hidden=!manage});const n=$('#socialNewPost');if(n)n.hidden=!create;const c=$('[data-social-tab="composer"]');if(c)c.hidden=!create}
window.switchSocialTab=switchSocialTab;$$('[data-social-tab]').forEach(b=>b.onclick=()=>switchSocialTab(b.dataset.socialTab));
function ensureSocialComposer(){if($('#socialComposerMount').dataset.ready)return;$('#socialComposerMount').dataset.ready='1';$('#socialComposerMount').innerHTML=`<div class="composer-premium"><div class="composer-editor"><div class="composer-head"><div><span class="eyebrow">COMPOSITOR MULTICANAL</span><h2>Transforma una idea en contenido para cada red</h2></div><span class="ai-pill">✦ IA asistida</span></div><div class="form social-form"><label>Nombre interno<input id="spName" placeholder="Ej. Lanzamiento Worktic AI"></label><label>Idea o contenido principal<textarea id="spMaster" rows="7" placeholder="Describe el mensaje, producto, promoción o historia que quieres comunicar..."></textarea></label><div class="grid2"><label>Objetivo<select id="spObjective"><option>Generar leads</option><option>Reconocimiento de marca</option><option>Tráfico a landing</option><option>Conversaciones por WhatsApp</option><option>Ventas</option></select></label><label>Formato<select id="spFormat"><option value="post">Publicación</option><option value="carousel">Carrusel</option><option value="reel">Reel / video corto</option><option value="story">Historia</option><option value="video">Video</option></select></label></div><div><b class="field-title">Selecciona las redes</b><div class="platform-selector">${Object.keys(socialPlatformMeta).map(p=>`<label class="platform-option"><input type="checkbox" value="${p}"><span>${socialBadge(p)}</span></label>`).join('')}</div></div><div class="grid2"><label>Llamado a la acción<input id="spCTA" placeholder="Ej. Empieza gratis hoy"></label><label>Enlace de destino<input id="spLink" placeholder="https://..."></label></div><label>Imagen o video (URL)<input id="spMedia" placeholder="https://..."></label><div class="grid2"><label>Fecha y hora<input id="spSchedule" type="datetime-local"></label><label>Acción<select id="spAction"><option value="draft">Guardar borrador</option><option value="schedule">Programar</option><option value="publish">Publicar ahora</option></select></label></div><div class="composer-actions"><button id="spGenerate" type="button" class="secondary">✦ Adaptar con IA</button><button id="spSave" type="button">Crear publicación multicanal</button></div></div></div><aside class="composer-preview"><div class="preview-top"><b>Vista previa</b><span id="previewPlatform">Selecciona una red</span></div><div id="socialPreview" class="phone-preview"><div class="preview-empty">Selecciona una red y escribe tu contenido para ver la adaptación.</div></div></aside></div>`;
 $$('.platform-option input').forEach(x=>x.onchange=renderSocialPreview);['spMaster','spCTA','spLink'].forEach(id=>$('#'+id).oninput=renderSocialPreview);$('#spGenerate').onclick=()=>{renderSocialPreview(true);toast('Versiones adaptadas por red')};$('#spSave').onclick=createSocialPost}
function selectedSocialPlatforms(){return $$('.platform-option input:checked').map(x=>x.value)}
function localAdapt(p,body,cta){let t=body.trim();if(p==='instagram')t+=`\n\n#WorkticAI #Ventas #Automatización #InteligenciaArtificial`;if(p==='linkedin')t=`Una mirada empresarial:\n\n${t}`;if(p==='telegram')t=`📣 ${t}`;if(p==='tiktok')t=`🎬 ${t}\n\n#ParaTi #Negocios`;if(p==='youtube')t=`▶️ ${t}`;if(cta)t+=`\n\n${cta}`;return t}
function renderSocialPreview(){const ps=selectedSocialPlatforms(),p=ps[0],body=$('#spMaster')?.value||'',cta=$('#spCTA')?.value||'';if(!p){$('#socialPreview').innerHTML='<div class="preview-empty">Selecciona una red para previsualizar.</div>';return}$('#previewPlatform').innerHTML=socialBadge(p);const text=localAdapt(p,body,cta),media=$('#spMedia')?.value||'';$('#socialPreview').innerHTML=`<div class="mock-post"><div class="mock-author"><span class="mock-avatar">W</span><div><b>Worktic AI</b><small>Ahora · ${socialPlatformMeta[p][0]}</small></div></div><p>${esc(text).replace(/\n/g,'<br>')||'Tu contenido aparecerá aquí.'}</p>${media?`<div class="mock-media"><img src="${esc(media)}" onerror="this.parentElement.innerHTML='<span>Vista previa multimedia</span>'"></div>`:`<div class="mock-media"><span>Imagen o video</span></div>`}<div class="mock-reactions"><span>♡ Me gusta</span><span>◯ Comentar</span><span>↗ Compartir</span></div></div>`}
async function createSocialPost(){const platforms=selectedSocialPlatforms();if(!$('#spMaster').value.trim())return toast('Escribe el contenido principal');if(!platforms.length)return toast('Selecciona al menos una red');const action=$('#spAction').value;if(action==='schedule'&&!$('#spSchedule').value)return toast('Selecciona fecha y hora');try{await api('/api/social/posts',{method:'POST',body:JSON.stringify({name:$('#spName').value,objective:$('#spObjective').value,masterContent:$('#spMaster').value,format:$('#spFormat').value,cta:$('#spCTA').value,linkURL:$('#spLink').value,mediaURL:$('#spMedia').value,scheduledAt:$('#spSchedule').value?new Date($('#spSchedule').value).toISOString():'',action,platforms})});toast('Contenido multicanal creado');['spName','spMaster','spCTA','spLink','spMedia','spSchedule'].forEach(id=>$('#'+id).value='');$$('.platform-option input').forEach(x=>x.checked=false);await loadSocialHub();switchSocialTab('library')}catch(e){toast(e.message)}}
window.openSocialComposer=()=>{switchSocialTab('composer');setTimeout(()=>$('#spMaster')?.focus(),100)};$('#socialNewPost').onclick=openSocialComposer;
function openSocialConnection(){if(!socialPerm('manage_connections'))return toast('Solo propietarios y administradores pueden conectar redes');modal(`<h2>Conectar red social</h2><p class="muted">Usa OAuth oficial para Meta, LinkedIn, TikTok y YouTube. Telegram se conecta mediante BotFather.</p><label>Red<select id="scPlatform">${Object.entries(socialPlatformMeta).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select></label><label>Modo<select id="scMode"><option value="official">API oficial</option><option value="sandbox">Sandbox / pruebas</option></select></label><div id="socialOfficialFields"></div><div class="notice">Las APIs oficiales requieren registrar Worktic AI, configurar las URL de retorno y obtener aprobación de permisos cuando el proveedor la exija.</div><div class="actions"><button type="button" id="saveSocialConnection">Continuar conexión</button><button value="cancel" class="secondary">Cancelar</button></div>`);
 const renderFields=()=>{const p=$('#scPlatform').value,m=$('#scMode').value,box=$('#socialOfficialFields');if(m==='sandbox'){box.innerHTML='<label>Nombre visible<input id="scName" placeholder="Ej. Worktic AI Colombia"></label><label>ID de prueba<input id="scExternal" placeholder="Opcional"></label>';return}if(p==='telegram'){box.innerHTML='<label>Nombre del canal<input id="scName" placeholder="Ej. Canal Worktic AI"></label><label>Token de BotFather<input id="scToken" type="password" autocomplete="off" placeholder="123456:ABC..."></label><label>ID o usuario del canal<input id="scChat" placeholder="@canal o -100..."></label>';return}box.innerHTML=`<div class="oauth-provider-card">${socialBadge(p)}<div><b>Conexión segura OAuth 2.0</b><small>Serás redirigido al proveedor para autorizar la cuenta.</small></div></div>`};
 $('#scPlatform').onchange=renderFields;$('#scMode').onchange=renderFields;renderFields();
 document.addEventListener('click',async function h(e){if(e.target?.id!=='saveSocialConnection')return;document.removeEventListener('click',h);const p=$('#scPlatform').value,m=$('#scMode').value;try{if(m==='official'&&p!=='telegram'){const r=await api('/api/social/oauth/start?platform='+encodeURIComponent(p));window.location.href=r.authorization_url;return}await api('/api/social/connections',{method:'POST',body:JSON.stringify({platform:p,account_name:$('#scName')?.value||('Cuenta '+socialPlatformMeta[p][0]),external_account_id:$('#scExternal')?.value||'',provider_mode:m,token:$('#scToken')?.value||'',chat_id:$('#scChat')?.value||''})});$('#modal').close();toast('Conexión guardada');loadSocialHub()}catch(err){toast(err.message)}})}
$('#socialConnect').onclick=openSocialConnection;$('#socialConnect2').onclick=openSocialConnection;
function renderSocialConnections(){const box=$('#socialConnectionsGrid'),manage=socialPerm('manage_connections');box.innerHTML=socialConnections.length?socialConnections.map(c=>`<article class="connection-card"><div class="connection-head">${socialBadge(c.platform)}<span class="status-chip ${c.status}">${c.status}</span></div><h3>${esc(c.account_name)}</h3><p>ID: ${esc(c.external_account_id)}</p><div class="connection-meta"><span>Modo <b>${esc(c.provider_mode)}</b></span><span>Permisos <b>${esc(c.scopes||'pendientes')}</b></span></div>${c.last_error?`<div class="notice">${esc(c.last_error)}</div>`:''}${manage?`<div class="actions"><button class="secondary" onclick="testSocialConnection(${c.id})">Probar</button><button class="danger" onclick="deleteSocialConnection(${c.id})">Eliminar</button></div>`:'<small class="muted">Conexión administrada por el propietario o administrador.</small>'}</article>`).join(''):`<div class="empty-premium wide"><b>No hay redes conectadas</b><p>${manage?'Conecta la primera cuenta social de la empresa.':'Solicita a un administrador que conecte las redes corporativas.'}</p>${manage?'<button onclick="document.querySelector(\'#socialConnect2\').click()">Conectar primera red</button>':''}</div>`}
window.testSocialConnection=async id=>{try{const r=await api('/api/social/test',{method:'POST',body:JSON.stringify({id})});toast(r.ok?'Conexión activa':'Conexión requiere atención')}catch(e){toast(e.message)}};window.deleteSocialConnection=async id=>{if(!await professionalConfirm({title:'Eliminar conexión',message:'Las publicaciones existentes se conservarán, pero no podrán enviarse por esta cuenta.',confirmText:'Eliminar',danger:true}))return;await api('/api/social/connections?id='+id,{method:'DELETE'});loadSocialHub()};
function renderSocialPosts(){const status=$('#socialStatusFilter')?.value||'',xs=status?socialPosts.filter(x=>x.status===status):socialPosts,publish=socialPerm('publish'),del=socialPerm('delete_content');$('#socialPostsTable').innerHTML=xs.length?`<div class="admin-table-wrap"><table class="table"><tr><th>Red</th><th>Contenido</th><th>Programación</th><th>Estado</th><th>Acciones</th></tr>${xs.map(x=>`<tr><td>${socialBadge(x.platform)}</td><td><b>${esc(x.title||'Publicación')}</b><small>${esc((x.caption||'').slice(0,100))}${(x.caption||'').length>100?'…':''}</small></td><td>${x.scheduled_at?new Date(x.scheduled_at).toLocaleString():'—'}</td><td><span class="status-chip ${x.status}">${x.status}</span>${x.error_message?`<small class="error-text">${esc(x.error_message)}</small>`:''}</td><td><div class="table-actions">${publish&&x.status!=='published'?`<button onclick="publishSocialPost(${x.id})">Publicar</button>`:''}${del?`<button class="danger" onclick="deleteSocialPost(${x.id})">Eliminar</button>`:''}</div></td></tr>`).join('')}</table></div>`:'<div class="empty-premium"><b>No hay publicaciones</b><p>Crea tu primera pieza multicanal.</p></div>'}
$('#socialStatusFilter').onchange=renderSocialPosts;window.publishSocialPost=async id=>{try{const r=await api('/api/social/publish',{method:'POST',body:JSON.stringify({id})});toast(r.sandbox?'Publicación simulada correctamente':'Publicado');loadSocialHub()}catch(e){toast(e.message);loadSocialHub()}};window.deleteSocialPost=async id=>{if(!await professionalConfirm({title:'Eliminar publicación',message:'La publicación será eliminada del calendario y la biblioteca.',confirmText:'Eliminar',danger:true}))return;await api('/api/social/posts?id='+id,{method:'DELETE'});loadSocialHub()};
function renderSocialCalendar(){const d=socialCalendarDate,y=d.getFullYear(),m=d.getMonth();$('#socialMonthLabel').textContent=d.toLocaleDateString('es',{month:'long',year:'numeric'});const first=new Date(y,m,1),last=new Date(y,m+1,0),offset=(first.getDay()+6)%7;let cells='';['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].forEach(x=>cells+=`<div class="calendar-weekday">${x}</div>`);for(let i=0;i<offset;i++)cells+='<div class="calendar-day muted-day"></div>';for(let day=1;day<=last.getDate();day++){const dateKey=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,items=socialPosts.filter(x=>(x.scheduled_at||x.created_at||'').slice(0,10)===dateKey);cells+=`<div class="calendar-day"><b>${day}</b>${items.slice(0,3).map(x=>`<div class="calendar-post ${x.platform}" title="${esc(x.title)}">${socialPlatformMeta[x.platform]?.[1]||'•'} ${esc(x.title||'Post')}</div>`).join('')}${items.length>3?`<small>+${items.length-3} más</small>`:''}</div>`}$('#socialCalendar').innerHTML=cells}
$('#socialPrevMonth').onclick=()=>{socialCalendarDate=new Date(socialCalendarDate.getFullYear(),socialCalendarDate.getMonth()-1,1);renderSocialCalendar()};$('#socialNextMonth').onclick=()=>{socialCalendarDate=new Date(socialCalendarDate.getFullYear(),socialCalendarDate.getMonth()+1,1);renderSocialCalendar()};
async function loadSocialAnalytics(){try{const f=$('#socialAnalyticsFrom')?.value,t=$('#socialAnalyticsTo')?.value,p=$('#socialAnalyticsPlatform')?.value;let q=[];if(f)q.push('from='+encodeURIComponent(f));if(t)q.push('to='+encodeURIComponent(t));if(p)q.push('platform='+encodeURIComponent(p));socialAnalytics=await api('/api/social/analytics'+(q.length?'?'+q.join('&'):''));renderSocialAnalytics()}catch(e){toast(e.message)}}
function fmtN(n){return new Intl.NumberFormat('es-ES',{notation:Number(n)>=100000?'compact':'standard',maximumFractionDigits:1}).format(Number(n)||0)}
function fmtPct(n){return (Number(n)||0).toFixed(2)+'%'}
function renderSocialAnalytics(){const a=socialAnalytics||{},k=a.kpis||{};$('#socialAnalyticsKPIs').innerHTML=[['Alcance',fmtN(k.reach)],['Impresiones',fmtN(k.impressions)],['Interacciones',fmtN(k.interactions)],['Engagement',fmtPct(k.engagement_rate)],['Clics',fmtN(k.clicks)],['CTR',fmtPct(k.ctr)],['Leads',fmtN(k.leads)],['Conversiones',fmtN(k.conversions)]].map(x=>`<div class="analytics-kpi"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('');const series=a.series||[],max=Math.max(1,...series.map(x=>Number(x.reach)||0));$('#socialTrendChart').innerHTML=series.length?series.map(x=>`<div class="trend-col" title="${x.date}: ${fmtN(x.reach)} alcance"><i style="height:${Math.max(4,(Number(x.reach)||0)/max*100)}%"></i><small>${x.date.slice(5)}</small></div>`).join(''):'<div class="empty-premium"><b>Aún no hay métricas sincronizadas</b><p>Conecta una API oficial y publica contenido para comenzar.</p></div>';const f=a.funnel||{};const steps=[['Impresiones',f.impressions],['Alcance',f.reach],['Interacciones',f.interactions],['Clics',f.clicks],['Leads',f.leads],['Conversiones',f.conversions]],base=Math.max(1,Number(f.impressions)||1);$('#socialFunnel').innerHTML=steps.map((x,i)=>`<div style="width:${Math.max(34,100-i*11)}%"><span>${x[0]}</span><b>${fmtN(x[1])}</b><small>${i?fmtPct((Number(x[1])||0)/base*100):'100%'}</small></div>`).join('');const by=a.by_platform||[];$('#socialByPlatform').innerHTML=by.length?by.map(x=>`<div class="platform-analytics-row">${socialBadge(x.platform)}<div><b>${fmtN(x.reach)} alcance</b><small>${fmtN(x.interactions)} interacciones · ${fmtPct(x.engagement_rate)} engagement · ${fmtN(x.conversions)} conversiones</small></div></div>`).join(''):'<div class="empty-premium"><p>Sin datos por red en este periodo.</p></div>';const top=a.top_posts||[];$('#socialTopPosts').innerHTML=top.length?top.map((x,i)=>`<div class="top-post-row"><span>${i+1}</span>${socialBadge(x.platform)}<div><b>${esc(x.title||'Publicación')}</b><small>${fmtN(x.reach)} alcance · ${fmtN(x.interactions)} interacciones · ${fmtN(x.conversions)} conversiones</small></div></div>`).join(''):'<div class="empty-premium"><p>Aún no hay publicaciones con métricas.</p></div>'}
const _today=new Date(),_from=new Date(Date.now()-29*86400000);if($('#socialAnalyticsFrom'))$('#socialAnalyticsFrom').value=_from.toISOString().slice(0,10);if($('#socialAnalyticsTo'))$('#socialAnalyticsTo').value=_today.toISOString().slice(0,10);if($('#socialAnalyticsRefresh'))$('#socialAnalyticsRefresh').onclick=loadSocialAnalytics;


(function socialOAuthFeedback(){const q=new URLSearchParams(location.search);if(q.get('social_oauth')){setTimeout(()=>toast(q.get('social_oauth')==='success'?'Red social conectada correctamente':'No fue posible completar OAuth: '+(q.get('reason')||'')),400);history.replaceState({},'',location.pathname)}})();
